import{_ as a,o,c as i,a5 as r}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 25 话 滚动驱动动画：scroll()/view() 纯 CSS 实现视差与进出场","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.25-scroll-driven-animations.md","filePath":"comics/css/EP.25-scroll-driven-animations.md","lastUpdated":1793421609000}'),n={name:"comics/css/EP.25-scroll-driven-animations.md"};function t(l,e,c,s,d,h){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-25-话-滚动驱动动画-scroll-view-纯-css-实现视差与进出场" tabindex="-1">漫画 · 第 25 话 滚动驱动动画：scroll()/view() 纯 CSS 实现视差与进出场 <a class="header-anchor" href="#漫画-·-第-25-话-滚动驱动动画-scroll-view-纯-css-实现视差与进出场" aria-label="Permalink to &quot;漫画 · 第 25 话 滚动驱动动画：scroll()/view() 纯 CSS 实现视差与进出场&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/15-scroll-driven-animations">docs/css/15-scroll-driven-animations.md</a> ｜ 原画：<a href="./EP.25-scroll-driven-animations.svg">EP.25-scroll-driven-animations.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。为博客添加阅读进度条和卡片进出场动画，写了 60 行 JS——scroll 监听、rAF、IntersectionObserver，维护成本高。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 <code>animation-timeline: scroll()</code> 和 <code>view()</code>，让 CSS 动画从「时间驱动」进化为「滚动驱动」。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>动画过渡章（EP.02）讲了 <code>@keyframes</code> + <code>animation-duration</code> 的时间驱动动画，但滚动场景需要「滚动位置决定动画进度」。像素酱先被 JS 滚动监听折磨——scroll 事件高频触发、主线程阻塞时动画卡顿、IntersectionObserver 需要手动管理。标签君引入滚动驱动动画：scroll() 跟踪滚动容器位置，view() 跟踪元素在视口中的可见进度，animation-range 精确控制触发区间。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>JS 滚动监听三大坑：scroll 事件在主线程高频触发，JS 阻塞时动画卡顿；IntersectionObserver 需要手动创建、观察、断开；60 行 JS 代码只为一个进度条和几个淡入动画。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>animation-timeline: scroll()</code> 将动画进度绑定到滚动容器位置，<code>animation-timeline: view()</code> 绑定到元素在视口中的可见进度。<code>animation-range: entry 0% entry 100%</code> 精确控制触发区间——刚进入视口时开始，完全进入时结束。<code>animation-duration</code> 被忽略，进度完全由滚动决定。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>三种时间轴对比：文档时间轴（默认）、scroll()（滚动容器）、view()（视口可见性）。animation-range 四种区间：entry（进入）、exit（离开）、cover（覆盖）、contain（完全可见）。命名时间轴 <code>scroll-timeline-name</code> + <code>timeline-scope</code> 实现跨元素联动。动画在合成器线程运行，零 JS，优先使用 transform 和 opacity。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>scroll() 跟踪滚动容器，view() 跟踪元素在视口中的可见进度。</li><li>animation-range 精确控制触发区间：entry / exit / cover / contain。</li><li>动画在合成器线程运行，优先使用 transform 和 opacity 避免 layout。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>animation-timeline: view()</code> 的默认 <code>animation-range</code> 是什么？为什么进出场动画通常需要显式指定 <code>entry 0% entry 100%</code>？</p><p><strong>答</strong>：默认是 <code>cover 0% cover 100%</code>，即元素从进入视口底部到离开视口顶部的整个过程。这意味着动画进度在元素完全离开后才会到达 100%——进出场动画（如淡入）在元素完全进入视口时就应该播完，所以需要显式指定 <code>entry 0% entry 100%</code>，让动画在元素完全进入视口时结束。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>页面进度条 + 卡片进出场 + 视差滚动 + 图片揭示 + timeline-scope 跨元素联动：<a href="./../../examples/css/15-scroll-driven-animations/index-01-scroll-driven-animations.html">examples/css/15-scroll-driven-animations/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 26 话《:has() 选择器》——CSS 的「父选择器」终于落地，表单验证、卡片有图变布局、数量感知，纯 CSS 实现 DOM 反向匹配。</p>',22)])])}const p=a(n,[["render",t]]);export{u as __pageData,p as default};
